const crypto = require('crypto');
const baseUrl = $json.baseUrl || 'https://mymiwallet.com';
const sharedSecret = $json.sharedSecret || '';
const jobs = $json.jobs || [];

async function signedRequest(path, method = 'GET', body = '') {
  const ts = Math.floor(Date.now() / 1000).toString();
  const msg = `${ts}\n${path}\n${body}`;
  const signature = crypto.createHmac('sha256', sharedSecret).update(msg).digest('base64');
  const options = {
    method,
    uri: `${baseUrl}${path}`
  };
  options.headers = {
    'X-MyMI-Timestamp': ts,
    'X-MyMI-Signature': signature
  };
  if (method === 'POST') {
    options.body = body;
    options.headers['Content-Type'] = 'application/json';
  }

  const response = await this.helpers.httpRequest(options);
  return typeof response === 'string' ? JSON.parse(response) : response;
}

const results = [];
for (const jobKey of jobs) {
  const dispatchBody = JSON.stringify({ job_key: jobKey });
  const dispatch = await signedRequest('/API/Ops/dispatch', 'POST', dispatchBody);
  const queueId = dispatch.queue_id;

  let status;
  for (let attempt = 0; attempt < 12; attempt++) {
    await new Promise((resolve) => setTimeout(resolve, 5000));
    status = await signedRequest(`/API/Ops/status?queue_id=${queueId}`, 'GET', '');
    if (status.queue_run && status.queue_run.status !== 'running') {
      break;
    }
  }

  const run = status?.queue_run || null;
  const markdown = run?.output_text || (run?.output_json ? JSON.stringify(run.output_json) : `Queue ${queueId} finished with status ${run?.status || 'unknown'}`);

  await signedRequest('/API/Ops/ingestReport', 'POST', JSON.stringify({
    job_key: jobKey,
    run_id: run?.id || null,
    queue_id: queueId,
    report_markdown: markdown
  }));

  results.push({
    job_key: jobKey,
    queue_id: queueId,
    status: run?.status || 'unknown',
    report_snippet: markdown.slice(0, 400)
  });
}

return results.map((row) => ({ json: row }));
